{
  "predictors": [
    {
      "name": "Supplier Concentration Risk",
      "construction": "Calculate the Herfindahl-Hirschman Index (HHI) of supplier concentration using data from firms' 10-K filings on major suppliers. Consider the top five suppliers and their respective sales to the firm.",
      "rationale": "Firms reliant on a few suppliers may face higher operational risks, potentially leading to higher risk premiums.",
