      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Patent Citation Growth",
      "construction": "Measure the year-over-year growth rate in the number of citations received by a firm's patents, using data from the U.S. Patent and Trademark Office.",
      "rationale": "Increasing citations may indicate valuable intellectual property, suggesting future growth potential not yet priced in.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "R&D Efficiency",
      "construction": "Divide the firm's incremental revenue by its R&D expense over the past three years, using Compustat data.",
      "rationale": "Firms that efficiently convert R&D expenditure into revenue growth may have a competitive advantage leading to superior future performance.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Green Investment Ratio",
      "construction": "Calculate the proportion of capital expenditure dedicated to environmentally sustainable projects, as reported in firm disclosures.",
      "rationale": "Firms investing heavily in sustainability may benefit from regulatory advantages and consumer preferences, increasing future profitability.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "CEO Media Exposure",
      "construction": "Count the number of media appearances by the firm's CEO over the past year using print and television sources.",
      "rationale": "High media exposure could indicate greater public scrutiny and potential overconfidence, impacting firm risk and return profile.",
      "higher_returns_for": "Low values of the measure"
    },
    {
      "name": "Legal Risk Exposure",
      "construction": "Calculate the number of ongoing legal proceedings or lawsuits disclosed in the annual report.",
      "rationale": "Firms with higher legal exposure may face greater uncertainties and potential financial liabilities, requiring higher returns as compensation.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Technological Adoption Rate",
      "construction": "Assess the rate of adoption of new technology as a ratio of technology-related expenses to total operating expenses over the last year.",
      "rationale": "Rapid technological adoption may signal adaptability and future growth potential, potentially underestimated by the market.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Customer Retention Rate",
      "construction": "Estimate the percentage of recurring sales from existing customers versus new customers using segment revenue disclosures.",
      "rationale": "High customer retention may indicate stable revenue streams and reduced marketing expense, improving profitability.",
      "higher_returns_for": "High values of the measure"
    },
    {
      "name": "Board Diversity Index",
      "construction": "Calculate a diversity score based on the gender, age, and ethnic diversity of board members from proxy statement disclosures.",
      "rationale": "Diverse boards may enhance decision-making and risk management, potentially leading to better long-term performance.",
      "higher_returns_for": "High values of the measure"
    }
  ]
}
